import numpy as np


def min_max_dist_dim2_16() -> np.ndarray:
    """Anneal a triangular seed, then polish active min/max distance contacts."""
    rng = np.random.RandomState(16016)
    rt3 = np.sqrt(3.0)
    removed = {(2, 0), (0, -2), (-2, 2)}
    axial = [
        (q, r)
        for q in range(-2, 3)
        for r in range(-2, 3)
        if max(abs(q), abs(r), abs(q + r)) <= 2 and (q, r) not in removed
    ]
    best = np.asarray(
        [[q + 0.5 * r, 0.5 * rt3 * r] for q, r in axial], dtype=float
    )

    def objective(x):
        d = x[:, None, :] - x[None, :, :]
        v = np.sum(d * d, axis=2)[np.triu_indices(16, 1)]
        return float(np.min(v) / np.max(v))

    current = best.copy()
    current_value = objective(current)
    best_value = current_value

    for iteration in range(120000):
        fraction = iteration / 120000.0
        step = 0.34 * (1.0 - fraction) ** 1.7 + 0.004
        candidate = current.copy()
        if iteration % 13 == 0:
            noise = rng.normal(size=(16, 2))
            noise -= noise.mean(axis=0, keepdims=True)
            candidate += 0.42 * step * noise
        else:
            k = int(rng.randint(16))
            candidate[k] += rng.normal(size=2) * step
        value = objective(candidate)
        temperature = 0.0007 * (1.0 - fraction) + 0.000002
        delta = value - current_value
        if delta > 0.0 or rng.rand() < np.exp(delta / temperature):
            current = candidate
            current_value = value
            if value > best_value:
                best = candidate.copy()
                best_value = value

    # Retain the annealed incumbent as a fallback while replacing boundary
    # blocks jointly with a deterministic polar-stencil beam search.
    annealed_best = best.copy()

    def incidence_order(x):
        """Rank points by incidence in near-minimum and near-diameter contacts."""
        delta = x[:, None, :] - x[None, :, :]
        matrix = np.sum(delta * delta, axis=2)
        upper = matrix[np.triu_indices(16, 1)]
        dmin, dmax = upper.min(), upper.max()
        incidence = np.zeros(16, dtype=int)
        for i, j in np.argwhere(np.triu(matrix <= dmin * 1.04, 1)):
            incidence[i] += 1
            incidence[j] += 1
        for i, j in np.argwhere(np.triu(matrix >= dmax * 0.96, 1)):
            incidence[i] += 1
            incidence[j] += 1
        return np.argsort(-incidence, kind="mergesort")

    order = incidence_order(best)
    angles = np.arange(24, dtype=float) * (2.0 * np.pi / 24.0)
    unit = np.column_stack((np.cos(angles), np.sin(angles)))
    centroid = best.mean(axis=0)
    radii = (0.92, 0.96, 1.00, 1.04, 1.08)

    for shift in range(3):
        block = order[shift:shift + 4]
        if len(block) != 4:
            continue
        core = np.delete(np.arange(16), block)
        stencil = []
        for k in block:
            v = best[k] - centroid
            radius = max(np.linalg.norm(v), 1.e-12)
            points = [
                centroid + radius * scale * direction
                for scale in radii for direction in unit
            ]
            points.append(best[k].copy())
            stencil.append(points)

        beam = [(best.copy(), frozenset(), best_value)]
        for pos, k in enumerate(block):
            expanded = []
            for state, used, _ in beam:
                for location in stencil[pos]:
                    key = (round(float(location[0]), 12),
                           round(float(location[1]), 12))
                    if key in used:
                        continue
                    candidate = state.copy()
                    candidate[k] = location
                    value = objective(candidate)
                    expanded.append(
                        (candidate, used | {key}, value)
                    )
            expanded.sort(key=lambda item: item[2], reverse=True)
            beam = expanded[:32]
            if not beam:
                break

        for candidate, _, value in beam:
            if value > best_value:
                best, best_value = candidate, value

        # Short exact angular polish for every surviving full replacement.
        for candidate, _, _ in beam:
            trial = candidate.copy()
            trial_value = objective(trial)
            for step in (0.003, 0.001, 0.000333333333333):
                improved = True
                while improved:
                    improved = False
                    for k in block:
                        for direction in unit:
                            probe = trial.copy()
                            probe[k] += step * direction
                            probe_value = objective(probe)
                            if probe_value > trial_value:
                                trial, trial_value = probe, probe_value
                                improved = True
            if trial_value > best_value:
                best, best_value = trial, trial_value

    if objective(annealed_best) > best_value:
        best = annealed_best
    best -= best.mean(axis=0)
    return np.asarray(best, dtype=float).reshape(16, 2)
